customCss:
/* BackupReader · 12a–12c. Tarjeta clara, título en serif, «Aceptar» y
   «Solo las necesarias» del mismo tamaño y «Elegir cuáles» como enlace. */
.cb-inner{background:#FFFFFF;color:#16233B;border:1px solid #D3D8DE;box-shadow:0 10px 30px rgba(22,35,59,.14)}
.cb-eyebrow{color:#16233B;font-family:'IBM Plex Serif',Georgia,serif;font-size:19px;font-weight:500;letter-spacing:-.005em;text-transform:none;margin:0 0 4px}
.cb-body{color:#3B4652;font-size:14px;line-height:1.5}
.cb-body a{color:#2A7062}
.cb-actions{display:flex;flex-wrap:wrap;gap:10px;justify-content:flex-start;align-items:center}
.cb-actions [data-a='accept']{order:1;background:#2F7E6C;color:#FBF8F1;border:0;border-radius:8px;padding:11px 20px;font-weight:600}
.cb-actions [data-a='accept']:hover{background:#2A7062}
.cb-actions [data-a='reject']{order:2;background:transparent;color:#16233B;border:1.5px solid #16233B;border-radius:8px;padding:10px 20px;font-weight:500}
.cb-actions [data-a='manage'].cb-ghost{order:3;flex-basis:100%;text-align:left;background:transparent !important;color:#2A7062 !important;border:0 !important;padding:4px 0 !important;font-weight:600}
/* Móvil: hoja inferior pegada al borde, botones apilados a ancho completo. */
@media (max-width:720px){
  .cb-banner{left:0 !important;right:0 !important;bottom:0 !important;transform:none !important;width:100% !important}
  .cb-inner{border-radius:18px 18px 0 0;border-left:0;border-right:0;border-bottom:0;padding:22px 20px 24px}
  .cb-actions{flex-direction:column;align-items:stretch}
  .cb-actions .cb-btn{width:100%;text-align:center;padding:14px 18px;font-size:15px}
  .cb-actions [data-a='manage']{text-align:center;padding:8px 0}
}
/* 12b: «Elige tus cookies». Diálogo centrado en escritorio; hoja inferior en
   móvil. Solo el botón «Guardar mi elección» abajo. */
.cb-panel{background:#FBF8F1;border-radius:14px}
.cb-eyebrow2,.cb-intro{display:none}
.cb-head{padding:22px 24px 14px;border-bottom:1px solid #D3D8DE}
.cb-panel h2{font-family:'IBM Plex Serif',Georgia,serif;font-size:21px;font-weight:500;color:#16233B}
.cb-row{padding:16px 24px;border-bottom:1px solid #E7EAEE}
.cb-row strong{font-size:15px;font-weight:600;color:#16233B}
.cb-row span{color:#3B4652}
.cb-pill{background:transparent;color:#5A6673;font-family:'IBM Plex Mono',monospace;font-size:11px;letter-spacing:.1em}
.cb-foot{background:transparent;padding:18px 24px 22px}
.cb-foot .cb-outline,.cb-foot .cb-text{display:none}
.cb-foot-right{width:100%}
.cb-save{width:100%;padding:14px 18px;font-size:15px;border-radius:8px}
@media (max-width:720px){
  .cb-overlay{align-items:flex-end;padding:0}
  .cb-panel{width:100%;max-width:100%;border-radius:18px 18px 0 0;max-height:88vh}
  .cb-panel:before{content:'';display:block;width:40px;height:4px;border-radius:2px;background:#D3D8DE;margin:10px auto 0}
}
